import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { relative, resolve } from 'node:path';

const root = fileURLToPath(new URL('../', import.meta.url));
// This file is generated from the shared JSON contract. No product file is exempt.
export const allowlist = new Map([
  [
    'app/design-tokens.css',
    'Generated by scripts/build-design-tokens.mjs from design-tokens.json.',
  ],
  [
    'app/routes/dashboard/v2/markup/model.ts',
    'Markup colors are drawn into the image pixels the agent reads; they are data, not theme.',
  ],
]);
const rules = [
  ['pixel font size', /font-size\s*:\s*[0-9.]+px\b/gi],
  ['arbitrary Tailwind type size', /text-\[[0-9.]+px\]/g],
  ['hex color', /#(?:[\da-f]{8}|[\da-f]{6}|[\da-f]{4}|[\da-f]{3})\b/gi],
  ['numeric RGB color', /rgba?\([\d ._,/]+\)/gi],
  // Shorthand and inline styles must also consume the shared type contract.
  ['pixel font shorthand', /\bfont\s*:[^;{}\n]*\b[0-9.]+px\b/g],
  ['inline pixel font size', /\bfontSize\s*[:=]\s*['"][0-9.]+(?:px)?['"]/g],
];
const failures = [];
function visit(directory) {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const path = resolve(directory, entry.name);
    if (entry.isDirectory()) visit(path);
    else if (/\.(css|tsx|ts)$/.test(entry.name)) {
      const name = relative(root, path).replaceAll('\\', '/');
      if (allowlist.has(name)) continue;
      const source = readFileSync(path, 'utf8');
      for (const [rule, pattern] of rules) {
        for (const match of source.matchAll(pattern)) {
          const line = source.slice(0, match.index).split('\n').length;
          failures.push(`${name}:${line}: ${rule}: ${match[0]}`);
        }
      }
    }
  }
}
visit(resolve(root, 'app'));
if (failures.length) {
  console.error(failures.join('\n'));
  console.error('Use app/design-tokens.json and semantic type/color tokens.');
  process.exitCode = 1;
} else {
  console.log('Design literals: no local pixel type sizes or literal colors.');
}
